export const BODY: string = "\n<p>كيف تصل أداة إلى حجم ملف دقيق مثل 80 كيلوبايت دون تخمين؟ الإجابة هي البحث الثنائي عن الجودة، وهو خوارزمية بسيطة وقوية.</p>\n<p>يجد البحث الثنائي أفضل إعداد جودة لصورتك في خطوات قليلة، دون تجربة عشرات الأرقام يدويًا.</p>\n<p>يشرح هذا المقال كيف يعمل البحث، ولماذا يتفوق على التحكم اليدوي في الجودة، ومتى يفشل.</p>\n<h2 id=\"the-problem\">المشكلة: الجودة لا يمكن التنبؤ بها</h2>\n<p>المشكلة أن الجودة لا يمكن التنبؤ بها. لا توجد معادلة تخبرك أن جودة 65 تعطي 80 كيلوبايت لصورتك تحديدًا، لأن كل صورة تستجيب بشكل مختلف.</p>\n<p>الصورة البسيطة قد تصل إلى 80 كيلوبايت بجودة 85، بينما الصورة المزدحمة قد تحتاج جودة 40. لذلك التخمين يفشل، والحل هو البحث.</p>\n<h2 id=\"binary-search-basics\">البحث الثنائي بكلمات بسيطة</h2>\n<p>البحث الثنائي بكلمات بسيطة: تخمّن رقمًا في المنتصف، ثم تضيّق النطاق إلى النصف في كل خطوة. مثل تخمين رقم بين 1 و100.</p>\n<p>إذا كان الملف الناتج أكبر من الهدف، تخفض الجودة. وإذا كان أصغر، ترفعها. كل اختبار يقص النطاق إلى النصف، فتصل إلى النتيجة بسرعة.</p>\n<h2 id=\"worked-example\">مثال عملي: الوصول إلى 100 كيلوبايت</h2>\n<p>مثال عملي: الوصول إلى 100 كيلوبايت. تبدأ الأداة بجودة 50، فإذا كان الملف 150 كيلوبايت تخفض إلى 25، وإذا أصبح 60 كيلوبايت ترفع إلى 37.</p>\n<p>بعد خطوات قليلة، تصل الأداة إلى أعلى جودة تناسب 100 كيلوبايت، مثل 63 بالمئة. النتيجة هي أوضح نسخة ممكنة عند هذا الحجم.</p>\n<h2 id=\"why-not-linear\">لماذا يتفوق البحث الثنائي على البحث الخطي؟</h2>\n<p>البحث الثنائي يتفوق على البحث الخطي لأنه أسرع بكثير. البحث الخطي يجرب كل رقم من 1 إلى 100، بينما البحث الثنائي يصل إلى النتيجة في نحو 7 خطوات.</p>\n<p>الفرق يهم عندما تضغط صورًا كثيرة. البحث السريع يعني دفعات أسرع وتجربة استخدام أفضل.</p>\n<h2 id=\"quality-first\">لماذا تأتي الجودة قبل الأبعاد؟</h2>\n<p>الجودة تأتي قبل الأبعاد لأن خفض الجودة يحافظ على حجم الصورة، بينما تقليص الأبعاد يقلل التفاصيل المتاحة من الأساس.</p>\n<p>لذلك تحاول الأداة الجودة أولًا بالحجم الكامل. ولا تقلّص الأبعاد إلا عندما لا تكفي الجودة وحدها للوصول إلى الهدف.</p>\n<h2 id=\"scaling-steps\">كيف تعمل خطوات تقليص الأبعاد؟</h2>\n<p>خطوات تقليص الأبعاد تعمل تدريجيًا: تخفض الأداة الأبعاد بنسبة صغيرة، ثم تعيد البحث عن الجودة، ثم تكرر إذا لزم الأمر.</p>\n<p>التقليص التدريجي يحافظ على أكبر قدر ممكن من التفاصيل. القفزات الكبيرة تضيع جودة دون داعٍ.</p>\n<h2 id=\"accuracy-limits\">الدقة وحدودها</h2>\n<p>الدقة لها حدود. البحث يجد أفضل جودة تناسب الهدف، لكن النتيجة قد تكون أقل بقليل من الهدف، مثل 78 كيلوبايت لهدف 80 كيلوبايت.</p>\n<p>هذا الفارق البسيط مقصود: الأداة تستهدف أقل بقليل لضمان الاجتياز مهما كان نظام التقريب في البوابة.</p>\n<h2 id=\"vs-manual\">البحث الثنائي مقابل التحكم اليدوي في الجودة</h2>\n<p>البحث الثنائي مقابل التحكم اليدوي في الجودة: اليدوي يعني تخمين رقم وتجربة النتيجة وتكرار المحاولة، وهي عملية بطيئة ومحبطة.</p>\n<p>البحث الثنائي يفعل ذلك تلقائيًا في ثوانٍ. النتيجة نفسها تقريبًا، لكن دون جهد أو تخمين منك.</p>\n<h2 id=\"batch-search\">البحث في وضع الدفعات</h2>\n<p>البحث في وضع الدفعات يطبق الخوارزمية نفسها على كل صورة في الدفعة. كل صورة تحصل على بحثها الخاص، فتصل كل واحدة إلى أفضل جودة تناسب الهدف.</p>\n<p>الدفعات تأخذ وقتًا أطول لأن كل صورة تحتاج بحثًا كاملًا، لكن النتيجة تستحق: كل صورة بأفضل جودة ممكنة عند الهدف نفسه.</p>\n<h2 id=\"when-search-fails\">عندما لا يستطيع البحث المساعدة</h2>\n<p>عندما لا يستطيع البحث المساعدة، فعادة لأن الهدف مستحيل. صورة جماعية مزدحمة بهدف 20 كيلوبايت لن تصل أبدًا مهما بحثت الخوارزمية.</p>\n<p>في هذه الحالة، غيّر الصيغة أو قصّ الصورة أو ارفع الهدف. البحث أداة ذكية، لكنه لا يستطيع كسر حدود الفيزياء.</p>\n<h2 id=\"search-history\">من أين جاء البحث الثنائي؟</h2>\n<p>البحث الثنائي قديم جدًا. يعود إلى بدايات علوم الحاسوب، حيث استُخدم للبحث في القوائم المرتبة بسرعة.</p>\n<p>تطبيقه على ضغط الصور حديث نسبيًا، لكن الفكرة نفسها: تقسيم المشكلة إلى نصفين في كل خطوة حتى تصل إلى الحل.</p>\n<h2 id=\"search-vs-ai\">البحث مقابل التخمين: لماذا تتفوق الطريقة على الحدس؟</h2>\n<p>البحث مقابل التخمين: الطريقة تتفوق على الحدس لأنها منهجية. الحدس قد يصيب أحيانًا، لكن البحث يصيب دائمًا وبسرعة.</p>\n<p>حتى الخبراء لا يستطيعون تخمين أفضل جودة لصورة لم يروها من قبل. البحث يزيل التخمين من المعادلة كاملة.</p>\n<h2 id=\"quality-steps\">ما مدى دقة خطوات الجودة؟</h2>\n<p>خطوات الجودة دقيقة بما يكفي. البحث يختبر مستويات بفارق صغير، فيجد النقطة المثالية دون الحاجة إلى اختبار كل رقم ممكن.</p>\n<p>الخطوات الأدق تعني بحثًا أبطأ، لذلك توازن الأداة بين الدقة والسرعة. النتيجة دقيقة بما يكفي لأي استخدام عملي.</p>\n<h2 id=\"edge-cases-search\">حالات حدّية: عندما لا يكون النطاق مرتبًا</h2>\n<p>الحالات الحدّية تحدث عندما لا يكون النطاق مرتبًا. إذا لم تؤدِّ الجودة الأعلى دائمًا إلى ملف أكبر، فقد يضل البحث طريقه.</p>\n<p>في الممارسة، هذا نادر جدًا مع صور JPG وWebP. العلاقة بين الجودة والحجم منتظمة بما يكفي ليعمل البحث بموثوقية.</p>\n<h2 id=\"search-and-scaling\">كيف يعمل البحث والتقليص معًا؟</h2>\n<p>البحث والتقليص يعملان معًا: البحث يجد أفضل جودة بالأبعاد الحالية، والتقليص يخفض الأبعاد عندما يستنفد البحث خياراته.</p>\n<p>التناوب بينهما يصل إلى أفضل نتيجة ممكنة: أعلى جودة بأكبر أبعاد تناسب الهدف. لا أحدهما وحده يكفي.</p>\n<h2 id=\"future-search\">ما القادم للبحث حسب الهدف؟</h2>\n<p>ما القادم للبحث حسب الهدف؟ الخوارزميات تتحسن، لكن المبدأ نفسه يبقى: البحث المنهجي يتفوق على التخمين.</p>\n<p>قد تأتي تحسينات في السرعة والدقة، لكن تجربة المستخدم ستبقى نفسها: اكتب هدفك واحصل على أفضل نتيجة. وللتفاصيل الكاملة، اقرأ <a href=\"/ar/blog/dalil-daght-as-sura-ila-hajm-muayyan/\">الدليل الكامل لضاغط حجم الملف المستهدف</a> و<a href=\"/ar/blog/kayfiyya-daght-as-sura-ila-kb-muhaddad/\">كيفية ضغط صورة إلى حجم دقيق بالكيلوبايت</a>، أو جرّب <a href=\"/ar/daght-as-sura-ila-hajm-muayyan/\">ضاغط حجم الملف المستهدف</a> بنفسك.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما هو البحث الثنائي عن الجودة؟","answer":"البحث الثنائي عن الجودة طريقة تجد أعلى جودة تناسب حجمًا مستهدفًا. تختبر مستوى جودة في المنتصف، ثم تضيّق النطاق إلى النصف في كل خطوة حتى تصل إلى أفضل نتيجة."},{"question":"لماذا يبدأ البحث من جودة 50؟","answer":"لأن الجودة 50 نقطة وسط جيدة. إذا كان الملف أكبر من الهدف، تخفض الأداة الجودة؛ وإذا كان أصغر، ترفعها. البدء من المنتصف يجعل البحث أسرع."},{"question":"هل يستطيع البحث إيجاد جودة 63 بدل رقم مستدير مثل 60 أو 70؟","answer":"نعم، وهذه نقطة قوة البحث. أفضل جودة لصورتك قد تكون 63 بالمئة لا رقمًا مستديرًا مثل 60 أو 70، والبحث يجد تلك النقطة بدقة."},{"question":"هل يعمل البحث بالطريقة نفسها لكل صورة؟","answer":"المبدأ نفسه يعمل لكل صورة، لكن النتيجة تختلف. الصور البسيطة تصل إلى جودة أعلى، والصور المزدحمة بالتفاصيل تصل إلى جودة أقل عند الهدف نفسه."},{"question":"لماذا تقلّل الأداة الأبعاد أحيانًا بدل خفض الجودة فقط؟","answer":"لأن الجودة وحدها لا تكفي أحيانًا للوصول إلى الهدف. عندما تصل الجودة إلى حدها الأدنى وما زال الملف أكبر من الهدف، تقلّص الأداة الأبعاد تدريجيًا."},{"question":"هل يُستخدم البحث الثنائي أيضًا في أدوات CompressMyPic الأخرى؟","answer":"نعم، أدوات الضغط إلى أحجام محددة في CompressMyPic تستخدم البحث الثنائي نفسه. إنها الطريقة القياسية للوصول إلى أي هدف حجم في الموقع."}];
